import json
import shutil
from pathlib import Path

import pytest

from tools import import_asd_ism, import_mscp
from tools.file_references import is_binary_payload
from tools.release_import import generate_release
from tools.source_lock import read_source_lock
from tools.validate_library import validate_library

REPO_ROOT = Path(__file__).resolve().parent.parent
BASELINES_DIR = REPO_ROOT / "baselines"

# Maintainer-written, never generated by an importer.
OVERLAYS_DIR_NAME = "_overlays"
MAPPINGS_DIR_NAME = "_mappings"
MAINTAINER_DIR_NAMES = (OVERLAYS_DIR_NAME, MAPPINGS_DIR_NAME)

IMPORTERS_BY_NAME = {
    importer.name: importer for importer in (import_mscp.IMPORTER, import_asd_ism.IMPORTER)
}


def committed_manifest() -> dict:
    return json.loads((BASELINES_DIR / "_manifest.json").read_text(encoding="utf-8"))


def current_release_tag(source_name: str) -> str:
    return next(source["release_tag"] for source in committed_manifest()["sources"] if source["name"] == source_name)


def current_release_dir(source_name: str) -> Path:
    return BASELINES_DIR / source_name / "releases" / current_release_tag(source_name)


def committed_releases() -> list[tuple[str, str]]:
    return [
        (source["name"], release["tag"])
        for source in committed_manifest()["sources"]
        for release in source["releases"]
    ]


COMMITTED_RELEASES = committed_releases()
COMMITTED_RELEASE_IDS = [f"{source_name}-{tag}" for source_name, tag in COMMITTED_RELEASES]


def files_under(directory: Path) -> dict[str, bytes]:
    return {
        path.relative_to(directory).as_posix(): path.read_bytes()
        for path in sorted(directory.rglob("*"))
        if path.is_file()
    }


def regenerate_release(source_name: str, tag: str, baselines_dir: Path) -> None:
    release_sources_dir = REPO_ROOT / "sources" / source_name / "releases" / tag
    generate_release(
        IMPORTERS_BY_NAME[source_name],
        release_sources_dir / "upstream",
        read_source_lock(release_sources_dir / "source.json"),
        baselines_dir,
    )


def committed_asd_ism_rules() -> list[dict]:
    rule_paths = sorted((current_release_dir("asd_ism") / "rules").glob("*.json"))
    return [json.loads(path.read_text(encoding="utf-8")) for path in rule_paths]


def test_committed_library_is_valid():
    assert validate_library(BASELINES_DIR) == []


@pytest.mark.parametrize(("source_name", "tag"), COMMITTED_RELEASES, ids=COMMITTED_RELEASE_IDS)
def test_committed_release_matches_regeneration(tmp_path, source_name, tag):
    # Regenerated into an empty library: publishing writes this one release and
    # a one-release manifest, so only that release's folder and manifest entry are compared.
    regenerated_dir = tmp_path / "baselines"

    regenerate_release(source_name, tag, regenerated_dir)

    release_path = Path(source_name) / "releases" / tag
    committed_files = files_under(BASELINES_DIR / release_path)
    regenerated_files = files_under(regenerated_dir / release_path)
    assert regenerated_files.keys() == committed_files.keys()
    assert [name for name in committed_files if committed_files[name] != regenerated_files[name]] == []

    committed_entry = next(
        release
        for source in committed_manifest()["sources"]
        if source["name"] == source_name
        for release in source["releases"]
        if release["tag"] == tag
    )
    regenerated_source = json.loads((regenerated_dir / "_manifest.json").read_text(encoding="utf-8"))["sources"][0]
    assert regenerated_source["releases"] == [committed_entry]


def test_regenerating_a_release_keeps_the_maintainer_folders(tmp_path):
    regenerated_dir = tmp_path / "baselines"
    for maintainer_dir_name in MAINTAINER_DIR_NAMES:
        shutil.copytree(BASELINES_DIR / maintainer_dir_name, regenerated_dir / maintainer_dir_name)

    regenerate_release("mscp", current_release_tag("mscp"), regenerated_dir)

    for maintainer_dir_name in MAINTAINER_DIR_NAMES:
        assert files_under(regenerated_dir / maintainer_dir_name) == files_under(BASELINES_DIR / maintainer_dir_name)


def test_every_manifest_source_has_an_importer():
    manifest = json.loads((BASELINES_DIR / "_manifest.json").read_text(encoding="utf-8"))
    assert sorted(source["name"] for source in manifest["sources"]) == sorted(IMPORTERS_BY_NAME)


def test_every_manifest_release_is_regenerated_by_this_suite():
    stored_releases = sorted(
        (source_dir.name, release_dir.name)
        for source_dir in (REPO_ROOT / "sources").iterdir()
        if source_dir.is_dir()
        for release_dir in (source_dir / "releases").iterdir()
        if release_dir.is_dir()
    )
    assert sorted(COMMITTED_RELEASES) == stored_releases


def test_committed_library_has_lf_line_endings_only():
    carriage_return_files = [
        path.relative_to(BASELINES_DIR).as_posix()
        for path in BASELINES_DIR.rglob("*")
        if path.is_file() and not is_binary_payload(path.name) and b"\r" in path.read_bytes()
    ]
    assert carriage_return_files == []


def test_binary_payload_types_are_marked_binary_for_git():
    attributes = (REPO_ROOT / ".gitattributes").read_text(encoding="utf-8").splitlines()
    text_rule = attributes.index("baselines/** text eol=lf")
    for extension in ("pol", "intunewin"):
        binary_rule = attributes.index(f"baselines/**/*.{extension} binary")
        assert binary_rule > text_rule, "a later .gitattributes line wins, so the binary rule must follow the text rule"


def test_vendored_license_present():
    license_text = (REPO_ROOT / "sources" / "mscp" / "releases" / current_release_tag("mscp") / "upstream" / "LICENSE.md").read_text(encoding="utf-8")
    assert "CC BY 4.0" in license_text


def test_asd_ism_vendored_license_present():
    readme_text = (REPO_ROOT / "sources" / "asd_ism" / "releases" / current_release_tag("asd_ism") / "upstream" / "README.md").read_text(encoding="utf-8")
    assert "Creative Commons Attribution 4.0" in readme_text


def test_asd_ism_titles_and_discussions_have_no_unresolved_links():
    rules = committed_asd_ism_rules()
    assert rules
    unresolved = [
        rule["id"] for rule in rules if "](#" in rule["discussion"] or "](#" in rule["title"]
    ]
    assert unresolved == []


def test_asd_ism_titles_are_single_paragraphs():
    rules = committed_asd_ism_rules()
    assert rules
    multi_paragraph_titles = [rule["id"] for rule in rules if "\n\n" in rule["title"]]
    assert multi_paragraph_titles == []


def test_asd_ism_multi_paragraph_statement_keeps_its_full_text_before_the_overview():
    incident_register = json.loads(
        (current_release_dir("asd_ism") / "rules" / "ism-1803.json").read_text(encoding="utf-8")
    )
    discussion = incident_register["discussion"]

    assert discussion.startswith(
        "A cyber security incident register contains the following for each cyber security incident:"
    )
    assert "- to whom the cyber security incident was reported." in discussion
    statement_end = discussion.index("- to whom the cyber security incident was reported.")
    statement_end += len("- to whom the cyber security incident was reported.")
    assert discussion[statement_end:].startswith("\n\nDeveloping, implementing and maintaining")


def test_asd_ism_multi_paragraph_statements_in_this_release_number_forty():
    rules = committed_asd_ism_rules()
    multi_paragraph_rules = [
        rule["id"] for rule in rules if rule["discussion"].startswith(rule["title"] + "\n\n")
    ]
    assert len(multi_paragraph_rules) == 40


def test_overlays_folder_is_not_a_source_and_keeps_lf_endings():
    manifest = json.loads((BASELINES_DIR / "_manifest.json").read_text(encoding="utf-8"))
    assert OVERLAYS_DIR_NAME not in [source["name"] for source in manifest["sources"]]
    overlay_paths = sorted((BASELINES_DIR / OVERLAYS_DIR_NAME / "rules").glob("*.json"))
    assert overlay_paths
    assert [path.name for path in overlay_paths if b"\r" in path.read_bytes()] == []


def test_mappings_folder_is_not_a_source_and_keeps_lf_endings():
    manifest = json.loads((BASELINES_DIR / "_manifest.json").read_text(encoding="utf-8"))
    assert MAPPINGS_DIR_NAME not in [source["name"] for source in manifest["sources"]]
    mappings_rules_dir = BASELINES_DIR / MAPPINGS_DIR_NAME / "rules"
    assert mappings_rules_dir.is_dir()
    mapping_paths = sorted(mappings_rules_dir.glob("*.json"))
    assert [path.name for path in mapping_paths if b"\r" in path.read_bytes()] == []
